#!/usr/bin/env python3
"""Stage 2 Year 3 English batch 03: 14 lesson-specific written content candidates.
Review needed: no NESA approval, media, validation or deployment implied.
"""
import json
from pipeline import ROOT, reconstruct, baseline_data, atomic_json
LESSONS=json.loads("[{\"seed_key\":\"s2-eng-y3-w07-l4\",\"title\":\"Finding reliable sources\",\"code\":\"EN2-RECOM-01\",\"principle\":\"A trustworthy source identifies where information came from, supplies evidence and can be checked against another source.\",\"model\":\"Two websites discuss koalas. One identifies an Australian wildlife organisation, author, publication date and sources; the other has no author and says koalas eat chocolate. I trust neither blindly, but I verify the first against a second authoritative reference.\",\"guided\":\"Two articles disagree about a frog's habitat. One is a museum fact sheet with a date and cited research; the other is an anonymous advertisement. Which would you consult first, and what would you still verify?\",\"feedback\":\"Start with the museum sheet, then compare its habitat claim against a second reputable source. Evidence and relevance matter more than a neat-looking page.\",\"misconception\":\"A website's professional design or its first place in search results does not prove accuracy.\",\"independent\":\"Research a NSW animal using two different reputable sources. Record their titles, organisations, dates where shown and URLs or publication details, list three facts that both support, flag one uncertain claim and explain which source you trust and why.\"},{\"seed_key\":\"s2-eng-y3-w08-l1\",\"title\":\"Fact versus opinion\",\"code\":\"EN2-RECOM-01\",\"principle\":\"A fact is a claim that can be checked using evidence. An opinion expresses a judgement or preference; a convincing opinion can still contain factual details.\",\"model\":\"'Wombats are marsupials' is a checkable scientific statement. 'Wombats are the most wonderful animals' is a judgement. 'Wombats can dig burrows, so I think they are fascinating' contains a fact plus an opinion.\",\"guided\":\"Classify: 'The swimming pool opens at nine' and 'Swimming is the best sport.' What evidence could check the first?\",\"feedback\":\"The opening time is checkable against the pool's schedule. 'Best' depends on someone's values or preference.\",\"misconception\":\"Do not label a statement a fact just because a confident speaker says it, or an opinion just because you disagree.\",\"independent\":\"Write six original statements about an activity, animal or place: three checkable factual claims and three clearly worded opinions. Underline any opinion language, describe how you could verify two claims and rewrite one mixed statement so fact and opinion are separate.\"},{\"seed_key\":\"s2-eng-y3-w08-l2\",\"title\":\"Writing a description paragraph\",\"code\":\"EN2-CWT-01\",\"principle\":\"A descriptive paragraph develops one main impression using purposeful sensory details and a logical focus instead of listing unrelated adjectives.\",\"model\":\"'The creek ran beneath twisted paperbarks. Cool water slipped around smooth stones, and the air smelled of wet leaves.' The details describe a single place through sight, touch and smell.\",\"guided\":\"Turn 'The park was nice' into two sentences with precise observations and at least two senses.\",\"feedback\":\"'The shady path crunched beneath my shoes. Magpies called from the gum trees.' The reader can picture and hear a particular park.\",\"misconception\":\"Not every sentence needs every sense; avoid inventing a taste or smell when the narrator could not experience it.\",\"independent\":\"Write a 100–140 word paragraph describing a local location from observation or memory. Begin with a clear topic sentence, choose at least three accurate sensory details, organise them from near to far or in walking order, and underline one deliberately precise verb.\"},{\"seed_key\":\"s2-eng-y3-w08-l3\",\"title\":\"Timeless present tense\",\"code\":\"EN2-CWT-01\",\"principle\":\"Information reports usually use the simple present for generally true characteristics and processes, not the past tense of a single event.\",\"model\":\"'Echidnas lay eggs' describes a general biological characteristic. 'An echidna crossed our driveway yesterday' describes a particular past event. The first belongs in a factual classification paragraph.\",\"guided\":\"Choose the correct form for a report: 'Frogs (begin/began) life as eggs' and explain.\",\"feedback\":\"'Frogs begin life as eggs' states a general process; 'began' would describe a particular completed event.\",\"misconception\":\"Not everything written in the present tense is timeless: 'I am looking at a frog now' is about this moment.\",\"independent\":\"Draft a five-sentence factual paragraph about an animal or weather process using general present-tense verbs. Underline each finite verb; then write one contrasting past-tense observation and explain why it does not belong among general facts.\"},{\"seed_key\":\"s2-eng-y3-w08-l4\",\"title\":\"Oral presentation skills\",\"code\":\"EN2-OLC-01\",\"principle\":\"Plan a clear opening, grouped points and conclusion; speak audibly at a pace that gives listeners time to understand.\",\"model\":\"Opening: 'Today I will explain three ways mangroves help a coastline.' Points: roots protect mud, animals find shelter, leaves manage salty conditions. Ending: 'Together these features make mangroves important habitats.' Cue notes prompt me without becoming a script.\",\"guided\":\"Give a 20-second opening for a talk about a favourite local place and state two points you will cover.\",\"feedback\":\"A clear opening names the topic and previews two relevant points: 'I'll tell you where the lookout is and why birds gather there.'\",\"misconception\":\"Reading every word from a slide can reduce connection with listeners; eye contact need not mean staring at one person.\",\"independent\":\"Prepare and deliver a 60–90 second factual presentation about a NSW place or animal, using four cue cards maximum. Record an opening, two organised facts with an explanation, and a conclusion. Self-assess volume, pace, clarity and one improvement after rehearsal.\"},{\"seed_key\":\"s2-eng-y3-w09-l1\",\"title\":\"Diagrams, graphs and captions\",\"code\":\"EN2-RECOM-01\",\"principle\":\"Information visuals each have a purpose: diagrams explain parts or processes, graphs display quantities, and captions help interpret what is shown.\",\"model\":\"A labelled frog-life-cycle diagram shows stages and arrows; a bar graph compares frog sightings by month; a caption such as 'Tadpoles develop legs before becoming froglets' interprets a stage without repeating a vague title.\",\"guided\":\"If you want to compare the number of birds seen in three gardens, choose a labelled diagram or a bar graph and justify.\",\"feedback\":\"A bar graph clearly compares quantities across gardens. A labelled drawing may identify body parts but does not display the counts as effectively.\",\"misconception\":\"A decorative picture without a useful label or caption is not evidence for a numerical claim.\",\"independent\":\"Create two static visual plans about a topic: a labelled process diagram with arrows and a small bar-graph dataset containing three categories and accurate counts. Write a precise caption for each; state the main information each reader should learn.\"},{\"seed_key\":\"s2-eng-y3-w09-l2\",\"title\":\"Writing a report with visuals\",\"code\":\"EN2-CWT-01\",\"principle\":\"An information report organises checked facts into headings and uses captioned visuals that teach information not easily conveyed by prose alone.\",\"model\":\"In a reef report, the heading 'Food webs' introduces a paragraph about producers and consumers. A simple labelled food chain adds relationships, and its caption explains what the arrows mean rather than saying 'Picture of fish'.\",\"guided\":\"Where would you place a labelled butterfly life cycle in a report: next to 'Life cycle' or beside 'How long butterflies live'? Explain.\",\"feedback\":\"Place it beside 'Life cycle', where readers need to see the stages; write a caption that clarifies the order and meaning of the arrows.\",\"misconception\":\"Do not invent statistics to make a graph attractive, and do not leave units off axes.\",\"independent\":\"Produce a 180–230 word information report about a living thing with two researched subheadings, three verified factual details, a hand-drawn or typed labelled diagram with an informative caption, and a note identifying where each fact was checked.\"},{\"seed_key\":\"s2-eng-y3-w09-l3\",\"title\":\"Compound and complex sentences\",\"code\":\"EN2-CWT-01\",\"principle\":\"A compound sentence links two independent clauses, often with and, but or so. A complex sentence includes a clause that cannot stand alone, introduced by words such as because, although or when.\",\"model\":\"Compound: 'The path was muddy, so we wore boots.' Both halves can stand alone. Complex: 'We wore boots because the path was muddy.' The 'because' part needs the main clause to complete its meaning.\",\"guided\":\"Combine 'Nia packed the lunch' and 'the group left early' using and, then express a reason using because.\",\"feedback\":\"Compound: 'Nia packed the lunch, and the group left early.' Complex: 'The group left early because the weather was changing.' The new reason is one possible completion.\",\"misconception\":\"Joining any two fragments with and does not automatically create two independent clauses.\",\"independent\":\"Write three compound and three complex sentences about an outdoor activity. Mark independent clauses, circle conjunctions, and explain why the because- or although-clause cannot stand alone.\"},{\"seed_key\":\"s2-eng-y3-w09-l4\",\"title\":\"Handwriting labels and captions\",\"code\":\"EN2-HANDW-01\",\"principle\":\"A useful handwritten label is brief, correctly connected to the drawing and legible; a caption adds a sentence that explains what the reader should notice.\",\"model\":\"For a flower drawing I label 'petal', 'stem' and 'leaf', with lines pointing to the correct parts. A caption says 'The stem supports the flower and carries water.' I keep letters large enough to read without crowding.\",\"guided\":\"Draft two labels and one caption for a drawing of a bicycle wheel and frame.\",\"feedback\":\"Labels could be 'spoke' and 'rim' with accurate arrows; caption: 'The spokes connect the hub to the rim and help support the wheel.'\",\"misconception\":\"A long caption cannot compensate for unclear arrows that point to the wrong feature.\",\"independent\":\"Draw and label a simple plant or everyday object. Add five accurate handwritten labels, a 15–25 word explanatory caption and a self-check of spacing, line placement and readability. Rewrite one cramped label more clearly.\"},{\"seed_key\":\"s2-eng-y3-w10-l1\",\"title\":\"Synthesising two texts\",\"code\":\"EN2-RECOM-01\",\"principle\":\"Synthesis combines information from two sources to explain a shared idea, while making differences clear and avoiding invented agreement.\",\"model\":\"Text A says mangroves shelter young fish. Text B says mangrove roots reduce erosion. Together: 'Mangroves help coastlines by providing habitat and holding sediment.' Neither text alone supports both reasons.\",\"guided\":\"One source describes bird migration routes; another explains why food changes by season. Write one sentence connecting them, without claiming either text states both.\",\"feedback\":\"'Seasonal food availability may help explain why some birds travel along migration routes.' This is a possible connection; the texts' exact evidence still needs citing.\",\"misconception\":\"Simply copying one sentence from each text side by side is not synthesis, and a possible connection is not a confirmed fact.\",\"independent\":\"Read two short, reliable texts on the same environmental topic. Make a three-column chart: source A, source B and combined conclusion. Identify two shared or complementary facts, one difference and a four-sentence synthesis with references to both sources.\"},{\"seed_key\":\"s2-eng-y3-w10-l2\",\"title\":\"Editing and publishing the report\",\"code\":\"EN2-CWT-01\",\"principle\":\"Before sharing an information report, revise factual organisation and evidence, then proofread grammar, punctuation, spelling, headings and captions.\",\"model\":\"Draft: 'Koalas eats leaves. They live all over the world.' Revision: 'Koalas eat mainly eucalypt leaves. They occur naturally in parts of eastern Australia.' I would verify range and diet with an authoritative source before publishing.\",\"guided\":\"Correct the language in 'The animal have thick fur and it sleep in trees'; identify what facts would need checking.\",\"feedback\":\"'The animal has thick fur and sleeps in trees.' Whether those claims are true depends on the animal and must be verified.\",\"misconception\":\"A spellchecker cannot establish that a factual claim is accurate or that a caption matches a diagram.\",\"independent\":\"Revise your earlier report or a supplied draft in two passes: factual meaning and structure first; sentence-level editing second. Produce a publishable 200-word version with source notes, headings and caption. Record three substantive changes and three proofread changes.\"},{\"seed_key\":\"s2-eng-y3-w10-l3\",\"title\":\"Punctuation review: commas and apostrophes\",\"code\":\"EN2-CWT-01\",\"principle\":\"Commas separate list items or some introductory clauses; apostrophes show contraction or possession. Choose the mark by meaning, not by where a pause happens.\",\"model\":\"List: 'We packed pencils, books and water.' Contraction: 'It's raining' means 'it is raining'. Possession: 'The dog's lead' means the lead belonging to one dog; 'dogs' without an apostrophe is simply plural.\",\"guided\":\"Punctuate: 'After lunch we packed maps snacks and coats' and 'the girls bag was heavy' (one girl).\",\"feedback\":\"'After lunch, we packed maps, snacks and coats.' 'The girl's bag was heavy.' The apostrophe signals one girl's possession.\",\"misconception\":\"'Its' means belonging to it; 'it's' means it is or it has. Not every plural word needs an apostrophe.\",\"independent\":\"Correct eight sentences of your own or from a short passage to demonstrate commas in lists, introductory phrases, one contraction and singular/plural possession. For four corrections, explain what the punctuation communicates.\"},{\"seed_key\":\"s2-eng-y3-w10-l4\",\"title\":\"Presenting the report\",\"code\":\"EN2-OLC-01\",\"principle\":\"Turn a written information report into a short spoken explanation with purposeful visual references, not a word-for-word reading.\",\"model\":\"A report has a detailed paragraph about how bees pollinate flowers. In a talk I say, 'When bees visit flowers for nectar, pollen can move between blossoms,' then point to labelled parts in my simple flower diagram.\",\"guided\":\"Explain one fact about an Australian animal using a labelled diagram; name what your listener should notice.\",\"feedback\":\"'Look at the claws labelled on the drawing. They help this animal grip tree bark.' The explanation adds meaning to the label.\",\"misconception\":\"A slide full of tiny text is not a substitute for an understandable spoken explanation.\",\"independent\":\"Present a 90-second report using your written report and one static illustration. Begin with a clear question or overview, explain three checked facts, refer accurately to the diagram, conclude, then assess voice, pace and audience understanding.\"},{\"seed_key\":\"s2-eng-y3-w11-l1\",\"title\":\"What makes a poem: rhyme and rhythm\",\"code\":\"EN2-RECOM-01\",\"principle\":\"Rhyme occurs when words share matching sounds near the end; rhythm is the pattern of stressed and unstressed beats in spoken lines. A poem may use either, both or neither.\",\"model\":\"'The small grey cat / curled on the mat' ends with cat/mat, which rhyme. The two lines can be read with an audible beat; changing where I stress words changes the rhythm.\",\"guided\":\"Choose a rhyme for 'light', then clap the natural stresses in 'The rain fell softly overnight'.\",\"feedback\":\"'Night' rhymes with 'light'. Clap stronger beats on words such as rain, soft and night according to a natural reading; rhythmic performance can vary.\",\"misconception\":\"Rhyming words do not need the same spelling, and poems are not required to rhyme.\",\"independent\":\"Read two short original poems or create your own two couplets. Mark rhyming end words, tap the rhythm as you read, compare the musical effect and write four original lines that intentionally use or avoid rhyme.\"}]")

def create():
 db=reconstruct()
 try:
  for u in LESSONS:
   row=db.execute("SELECT * FROM lessons WHERE seed_key=?",(u['seed_key'],)).fetchone()
   if row is None: raise ValueError("Missing seed "+u['seed_key'])
   base=baseline_data(row)
   l={k:v for k,v in base.items() if k in ('seed_key','stage','learning_area','year_level','week','lesson_number','lesson_role','unit_title','unit_number','week_in_unit','subject')}
   rule=u['principle']; model=u['model']; prompt=u['guided']; answer=u['feedback']; pitfall=u['misconception']; task=u['independent']
   l.update(title=base['title'],child_mission=rule,learning_intention=rule,
      success_criteria=['Explain the specific technique from a model','Use it on a new relevant example','Independently produce clear written or oral evidence','Explain an improvement based on meaning'],
      outcome_codes=[u['code']],review_status='unreviewed',**{'pass':1,'pass_mark':0.9},
      materials=['Paper or typed answer space','Pencil'],duration_minutes=55,coming_soon=None)
   phases=[
      ('Understand and model',rule,model,prompt,answer,pitfall),
      ('Explain the evidence','Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.',model+' Think about how this word or relationship creates meaning.','Underline or quote one precise detail in the model and explain its effect.',answer,'Saying a choice is good without naming the actual detail does not show understanding.'),
      ('Test a misconception','Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.',pitfall+' Here is a more productive model: '+model,'Describe why the warned-against approach would weaken your work.',answer,'A superficial change in length or appearance does not repair meaning.'),
      ('Transfer to an independent example','Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.',rule+' Now choose different people, facts or text to show you can transfer the idea.','Make one fresh example demonstrating the skill and explain your main choice.','The new example should meet the same purpose as the model, but contain original material.','Repeating the worked example cannot show transfer to new content.')
   ]
   l['teach_steps']=[]; evidence=[]
   for i,(heading,idea,demonstration,attempt,fb,error) in enumerate(phases):
    why='This helps the learner make decisions based on specific language evidence, rather than guess or copy someone else.'
    explain=(idea+'\n\nWHY IT MATTERS\n'+why+'\n\nHOW TO WORK\n'
      'Read the original example and locate the words or actions that support the idea. '
      'Before looking at the correction, make your own attempt using the exact question provided. '
      'Check your response against the feedback: did you address the same skill and show your reasoning? '
      'If a detail is uncertain, identify what would have to be checked. '
      'One deliberate, justified revision is more useful than making the answer longer.')
    l['teach_steps'].append(dict(title=heading,icon='📖',explain=explain,
       example='WORKED MODEL\n'+demonstration+'\n\nTRY FIRST\n'+attempt+'\n\nFEEDBACK\n'+fb,
       notice=error+' Correct the meaning, not just the appearance.',
       check=dict(question='What should you demonstrate in this teaching stage?',
         options=[idea,'A claim unrelated to the text.','An answer copied without understanding.','A guess with no explanation.'],
         correct_index=0,explanation=idea+' A supported explanation follows the actual words and purpose of the task.')))
    evidence.append(dict(rule=idea,why=why,model=demonstration,
      misconception=error,fix='Correct the meaning, not just the appearance.',
      guided_attempt=attempt,feedback=fb))
   l['worked_example']='WORK THROUGH THIS\n'+model+'\n\nExplain what makes this example accurate and effective, identifying its specific wording.'
   l['guided_practice']='PRACTISE BEFORE READING THE FEEDBACK\n'+prompt+'\n\nFEEDBACK\n'+answer+'\n\nCHECK\n'+pitfall
   l['independent_task']='INDEPENDENT EVIDENCE\n'+task+'\n\nWrite a short reflection describing one specific revision you made and why.'
   l['response_prompt']='Include your independent task and reflection, with explanations where requested.'
   # Candidate assessments are editorial drafts. They require authored distractors,
   # independent review and specific NESA point verification before acceptance.
   q=[]
   for heading,idea,demonstration,attempt,fb,error in phases:
    q.append(dict(type='multiple_choice',question='Which idea best explains '+heading.lower()+' in this lesson?',
      options=[idea,'More adjectives always improve writing.','Claims need no evidence.','The original question can be ignored.'],
      correct_index=0,explanation=idea+' The other choices do not match the model or learning intention.'))
    q.append(dict(type='multiple_choice',question='Which response accurately addresses this practice: '+attempt,
      options=[fb,'An unrelated sentence answers the question.','Skip this practice when the answer is uncertain.','Copy the model regardless of the new task.'],
      correct_index=0,explanation=fb+' A correct response addresses this question instead of inventing unsupported content.'))
   q.append(dict(type='short_answer',question='Produce a fresh example demonstrating the central skill, explaining the particular words or evidence that make it work.',
       sample_answer=model,marking_guide='Require independently produced relevant work with accurate reasoning and a specific supporting detail.',explanation='Independent evidence, not repetition of the worked model, demonstrates the skill.'))
   q.append(dict(type='short_answer',question='Name one likely error in using this skill, correct it and explain why the correction helps.',
       sample_answer=pitfall+' A better response follows: '+answer,marking_guide='Require an actual misconception plus corrected example and purpose-linked explanation.',explanation='A correction needs to change meaning or accuracy, not just make the text longer.'))
   l['quiz']=q
   l['parent_notes']='Parent answer guidance: '+answer+'\nLikely misconception: '+pitfall+'\nIndependent task evidence: '+task+'\nAssess accurate meaning, examples and explanation; accept equivalent original responses. Do not expose sample answers to child role.'
   l['evidence_instructions']='Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.'
   l['offline_alternative']='Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.'
   l['extension']='Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.'
   hint_data={
      'accept':['Read the lesson purpose carefully.','Find the teaching concept you need to practise.','You will learn: '+rule],
      'teach0':['Identify the specific technique.','Find the choice made in the model.','Original teaching point: '+rule],
      'teach1':['Read the model before explaining.','Quote the exact action or word that supports the point.','Model evidence: '+model],
      'teach2':['Think about the common mistake in this task.','Decide how to repair meaning, not just appearance.','Misconception to avoid: '+pitfall],
      'teach3':['Choose a fresh subject for your example.','Check that the same skill works on new content.','Independent target: '+task[:160]],
      'learn':['Focus on the demonstrated example.','Say how its language or structure achieves its purpose.','Worked example: '+model],
      'guided':['Try before opening the solution.','Compare the reason for your choice with the feedback.','Correction: '+answer],
      'write':['Locate every required part of the independent task.','Show your original evidence and explain a revision.','Task reminder: '+task[:170]],
      'quiz':['Read the exact question and answer options.','Choose based on evidence instead of appealing wording.','Keep in mind: '+pitfall],
      'submit':['Check that your response is original and complete.','Explain at least one particular choice or correction.','Success means you can: '+rule]}
   l['stage_hints']=hint_data
   # No animation/multimedia. Static illustrative media is a separate Written
   # Core editorial task and remains an explicit acceptance gap.
   l['worked_visuals']=[]
   for key in ('resources','word_challenges','sort_activity','suspense_builder','planner_fields','planner_title','planner_intro','spelling','spelling_focus','hoard_words','follow_up_challenges','printable_resource','interactive_activities','explicit_teaching'):
    l[key]=None
   bundle=dict(architecture='d1-worker',lesson=l,
     curriculum=[dict(code=u['code'],source='https://curriculum.nsw.edu.au/learning-areas/english/english-k-10-2022/outcomes',
       verification_status='pending',lesson_evidence=rule,scope_limit='Single lesson: partial evidence. Cross-check existing card mapping and NESA content point.')],
     requirements=dict(teaching=evidence,
       practice=dict(model_inputs=[model],guided_inputs=[prompt],independent_inputs=[task]),visuals=[],
       review_questions=['Check original Coming Soon outcome mapping against current NESA.',
         'Replace generated generic quiz distractors with lesson-specific questions and answer explanations.',
         'Add instructional static visuals where useful in this written phase.',
         'Independently verify accuracy, privacy and child experience.']))
   out=ROOT/'lesson-pipeline/authored'/f"{u['seed_key']}.json"
   atomic_json(out,bundle)
   print('candidate written bundle',out)
 finally:
  db.close()
if __name__=='__main__': create()
